/*
 * A061478  First (leftmost) digit - second digit + third digit - fourth digit
 *          .... = 9.
 * https://oeis.org/A061478
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the smallest integer x such that the alternating sum *
 *            of its decimal digits (starting with + for the most significant
 *            digit) * equals 9. The sequence is generated by iteratively
 *            finding the next * such integer greater than the previous one
 * Range:     u8 n <= 7, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   alt_sum_is_9
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/alt_sum_is_9.h"

/* Static cache of computed terms. */
static seq_t *cache          = NULL;
static idx_t cache_size      = 0;
static idx_t cache_capacity  = 0;

/* Return the n-th term of the sequence (n >= 1). */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;      /* sequence is defined only for n >= 1 */

    /* Initialise cache on first call. */
    if (cache == NULL) {
        cache_capacity = 128;
        cache          = (seq_t *)malloc(sizeof(seq_t) * cache_capacity);
        cache_size     = 0;
    }

    /* Generate terms until we have at least n of them. */
    while (cache_size < n) {
        seq_t cand;
        if (cache_size == 0)          /* first candidate starts at 1 */ 
            cand = (seq_t)1;
        else
            cand = cache[cache_size - 1] + (seq_t)1;

        /* Find the next integer satisfying the alternating‑sum test. */
        while (!alt_sum_is_9(cand)) {
            cand = cand + (seq_t)1;
        }

        /* Resize cache if necessary. */
        if (cache_size == cache_capacity) {
            cache_capacity *= 2;
            cache = (seq_t *)realloc(cache, sizeof(seq_t) * cache_capacity);
        }

        cache[cache_size++] = cand;
    }

    return cache[n - 1];
}
